// partner and partner_assignment row-level security — generated by `pnpm gen:migration`; cases for E1 AC4
// and CLAUDE.md §3 rule 5 (partners are anonymous to clients) added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  inActorTransaction,
  migrateUp,
  partner,
  partnerAssignment,
  type Database,
  type DbActor,
} from '../index.ts';

const REAL_NAME = 'Installer Company 01';
const clientA = randomUUID();
const clientB = randomUUID();
const partnerId = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const userOfB: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientB] };
const partnerUser: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
let testDb: TestDatabase;
let database: Database;

const as = <T>(actor: DbActor, read: Parameters<typeof inActorTransaction<T>>[2]) =>
  inActorTransaction(database.db, actor, read);

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await as(staff, async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx.insert(partner).values({ id: partnerId, realName: REAL_NAME, countryCode: 'ES' });
    await tx.insert(partnerAssignment).values([
      { id: randomUUID(), clientId: clientA, partnerId, letter: 'A' },
      { id: randomUUID(), clientId: clientB, partnerId, letter: 'C' },
    ]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff read real partner names', async () => {
  expect((await as(staff, (tx) => tx.select().from(partner))).map((p) => p.realName)).toEqual([REAL_NAME]);
});

it('no client and no partner user can read a real partner name', async () => {
  for (const actor of [userOfA, userOfB, partnerUser]) {
    expect(await as(actor, (tx) => tx.select().from(partner))).toEqual([]);
  }
});

it('a client sees only its own assignments, each with its own letter', async () => {
  const letters = async (actor: DbActor) =>
    (await as(actor, (tx) => tx.select().from(partnerAssignment))).map((a) => a.letter);
  expect(await letters(userOfA)).toEqual(['A']);
  expect(await letters(userOfB)).toEqual(['C']);
  expect(await letters(partnerUser)).toEqual([]);
});

it('a client cannot write partners or assignments', async () => {
  await expect(
    as(userOfA, (tx) => tx.insert(partner).values({ id: randomUUID(), realName: 'X', countryCode: 'ES' })),
  ).rejects.toThrow();
  await expect(
    as(userOfA, (tx) =>
      tx.insert(partnerAssignment).values({ id: randomUUID(), clientId: clientA, partnerId, letter: 'B' }),
    ),
  ).rejects.toThrow();
});

it('a letter and a partner appear once per client', async () => {
  const other = randomUUID();
  await as(staff, (tx) =>
    tx.insert(partner).values({ id: other, realName: 'Installer Company 02', countryCode: 'PT' }),
  );
  await expect(
    as(staff, (tx) =>
      tx
        .insert(partnerAssignment)
        .values({ id: randomUUID(), clientId: clientA, partnerId: other, letter: 'A' }),
    ),
  ).rejects.toThrow();
  await expect(
    as(staff, (tx) =>
      tx.insert(partnerAssignment).values({ id: randomUUID(), clientId: clientA, partnerId, letter: 'B' }),
    ),
  ).rejects.toThrow();
});
